#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void add_one(char *s, int *len) {
    int i = *len - 1;
    while (i >= 0 && s[i] == '9') {
        s[i] = '0';
        i--;
    }
    if (i >= 0) {
        s[i]++;
    } else {
        memmove(s + 1, s, *len);
        s[0] = '1';
        (*len)++;
        s[*len] = '\0';
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char *digits = (char *)malloc((n + 5) * sizeof(char));
    for (int i = 0; i < n; i++) {
        int d;
        scanf("%d", &d);
        digits[i] = (char)('0' + d);
    }
    digits[n] = '\0';

    char *cur = (char *)malloc((n + 5) * sizeof(char));

    for (int l = 1; l <= n; l++) {
        // Se L < N e os primeiros l dígitos começam com '0', não é um número válido (já que A >= 1)
        if (digits[0] == '0') {
            // A >= 1, então o primeiro dígito não pode ser 0
            break;
        }

        // Inicializa o número corrente com os primeiros L dígitos
        memcpy(cur, digits, l);
        cur[l] = '\0';
        int cur_len = l;

        int idx = 0;
        int ok = 1;

        while (idx < n) {
            if (idx + cur_len > n) {
                ok = 0;
                break;
            }
            if (memcmp(digits + idx, cur, cur_len) != 0) {
                ok = 0;
                break;
            }
            idx += cur_len;
            if (idx == n) {
                break;
            }
            add_one(cur, &cur_len);
        }

        if (ok && idx == n) {
            // Encontramos o menor A, que é o prefixo de tamanho L
            for (int i = 0; i < l; i++) {
                putchar(digits[i]);
            }
            putchar('\n');
            free(digits);
            free(cur);
            return 0;
        }
    }

    free(digits);
    free(cur);
    return 0;
}
